    """
    Parse a JSON string into Python objects using a state machine approach to recognize different JSON components 
    based on the current state of parsing.
    """

    class StateMachine:
        def __init__(self, input_string):
            self.s = input_string
            self.index = 0
            self.length = len(input_string)

        def next(self):
            if self.index < self.length:
                char = self.s[self.index]
                self.index += 1
                return char
            return None

        def peek(self):
            if self.index < self.length:
                return self.s[self.index]
            return None

        def skip_whitespace(self):
            while self.index < self.length and self.s[self.peek()].isspace():
                self.index += 1

    def parse_value(machine: StateMachine):
        machine.skip_whitespace()
        char = machine.peek()
        if char == '"':
            return parse_string(machine)
        elif char in '-0123456789':
            return parse_number(machine)
        elif machine.s.startswith('true', machine.index):
            machine.index += 4
            return True
        elif machine.s.startswith('false', machine.index):
            machine.index += 5
            return False
        elif machine.s.startswith('null', machine.index):
            machine.index += 4
            return None
        elif char == '[':
            return parse_array(machine)
        elif char == '{':
            return parse_object(machine)
        else:
            raise ValueError(f"Unexpected character: {char} at index {machine.index}")

