def parse_json(s: str) -> object:
    """
    Parse a JSON string into Python objects using an iterative approach with a stack 
    to track the current context (objects, arrays, and values) and effectively handle nesting.
    """

    stack = []
    current = None
    i = 0
    n = len(s)

    while i < n:
        c = s[i]

        if c.isspace():
            i += 1
            continue

        if c == '{':
            new_obj = {}
            if current is not None:
                if isinstance(current, list):
                    current.append(new_obj)
                else:
                    raise ValueError("Invalid object placement")
            current = new_obj
            stack.append(current)
            i += 1

        elif c == '}':
            if len(stack) == 0:
                raise ValueError("Unexpected closing brace")
            current = stack.pop()
            i += 1

        elif c == '[':
            new_arr = []
            if current is not None:
                if isinstance(current, list):
                    current.append(new_arr)
                else:
                    raise ValueError("Invalid array placement")
